// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address dest, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        uint256 preC = address(c).balance;
        bool reverted;
        try c.multiplicate{value: amount}(dest) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 postC = address(c).balance;
        assertTrue(reverted || postC >= preC);
    }

    function testFuzz_run(address dest, uint256 amount) public {
        vm.assume(dest.code.length == 0 && uint160(dest) > 0xffff && dest != address(this) && dest != address(c) && dest != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && dest != 0x000000000000000000636F6e736F6c652e6c6f67 && dest != 0x4e59b44847b379578588920cA78FbF26c0B4956C && dest != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(dest, amount);
    }

    receive() external payable {}
}
